enabled=1" >> /etc/yum.repos.d/nginx.repo yum -y install nginx } function download_php() { wget -c  } function install_php() { #install support libs yum -y install libxml2 libxml2-devel curl curl-devel libjpeg libjpeg-devel libpng libpng-devel libmcrypt libmcrypt-devel mhash mcrypt libtool-ltdl libtool-ltdl-devel bzip2 bzip2-devel freetype freetype-devel openldap openldap-devel openssl openssl-devel cp -frp /usr/lib64/libldap* /usr/lib/ #install php tar -jxvf php-5.6.29.tar.bz2 &amp;&amp; cd php-5.6.29 &amp;&amp; ./configure --with-apxs2=/usr/sbin/apxs --with-mysql=mysqlnd --with-mysqli=mysqlnd --with-mysql-sock --with-pdo-mysql=mysqlnd --with-openssl --with-gd --with-iconv --with-jpeg-dir=/usr/local/lib --with-png-dir --with-freetype-dir --with-zlib --with-bz2 --with-libxml-dir --with-gettext --with-curl --with-mhash --with-mcrypt --enable-mbstring --enable-mbregex --with-ldap --with-ldap-sasl --with-xmlrpc --enable-gd-native-ttf --enable-pdo --enable-pcntl --enable-sockets --enable-bcmath --enable-xml --enable-zip --enable-soap --enable-bcmath --enable-shmop --enable-sysvsem --enable-inline-optimization --enable-maintainer-zts --enable-opcache --enable-cgi --without-pear --disable-phar >> ../install_php_log &amp;&amp; make >> ../install_php_log &amp;&amp; make install >> ../install_php_log &amp;&amp; cd ../ #config PHP cp ./php-5.6.29/php.ini-development $(php-config --prefix)/lib/php.ini &amp;&amp; sed -i 's/\;date\.timezone \=/date\.timezone \=PRC/g' $(php-config --prefix)/lib/php.ini &amp;&amp; sed -i "s/\;include_path \= "\.\:/php/includes"/include_path \= "\$\(php-config --prefix\)/lib/php"/g" $(php-config --prefix)/lib/php.ini &amp;&amp; ln -s $(php-config --prefix)/bin/php /usr/bin/php echo "AddHandler application/x-httpd-php .php" >> /etc/httpd/conf/httpd.conf echo "" > /var/www/html/i.php } function install_phpfpm() { #install support libs yum -y install libxml2 libxml2-devel curl curl-devel libjpeg libjpeg-devel libpng libpng-devel libmcrypt libmcrypt-devel mhash mcrypt libtool-ltdl libtool-ltdl-devel bzip2 bzip2-devel freetype freetype-devel openldap openldap-devel openssl openssl-devel cp -frp /usr/lib64/libldap* /usr/lib/ #install php tar -jxvf php-5.6.29.tar.bz2 &amp;&amp; cd php-5.6.29 &amp;&amp; ./configure --enable-fpm --enable-cgi --with-mysql=mysqlnd --with-mysqli=mysqlnd --with-mysql-sock --with-pdo-mysql=mysqlnd --with-openssl --with-gd --with-iconv --with-jpeg-dir=/usr/local/lib --with-png-dir --with-freetype-dir --with-zlib --with-bz2 --with-libxml-dir --with-gettext --with-curl --with-mhash --with-mcrypt --enable-mbstring --enable-mbregex --with-ldap --with-ldap-sasl --with-xmlrpc --enable-gd-native-ttf --enable-pdo --enable-pcntl --enable-sockets --enable-bcmath --enable-xml --enable-zip --enable-soap --enable-bcmath --enable-shmop --enable-sysvsem --enable-inline-optimization --enable-maintainer-zts --enable-opcache --enable-cgi --without-pear --disable-phar >> ../install_php_log &amp;&amp; make >> ../install_php_log &amp;&amp; make install >> ../install_php_log &amp;&amp; cd ../ #config PHP cp ./php-5.6.29/php.ini-development $(php-config --prefix)/lib/php.ini &amp;&amp; sed -i 's/\;date\.timezone \=/date\.timezone \=PRC/g' $(php-config --prefix)/lib/php.ini &amp;&amp; sed -i "s/\;include_path \= "\.\:/php/includes"/include_path \= "\$\(php-config --prefix\)/lib/php"/g" $(php-config --prefix)/lib/php.ini &amp;&amp; ln -s $(php-config --prefix)/bin/php /usr/bin/php #config php-fpm. use -t test fpm&rsquo;s configs cp ./php-5.6.29/sapi/fpm/init.d.php-fpm /etc/init.d/php-fpm &amp;&amp; chmod a+x /etc/init.d/php-fpm &amp;&amp; chkconfig --add php-fpm &amp;&amp; chkconfig php-fpm on &amp;&amp; cp /usr/local/etc/php-fpm.conf.default /usr/local/etc/php-fpm.conf &amp;&amp; /usr/local/sbin/php-fpm -c $(php-config --prefix)/lib/php.ini -y /usr/local/etc/php-fpm.conf -t &amp;&amp; /usr/local/sbin/php-fpm -c $(php-config --prefix)/lib/php.ini -y /usr/local/etc/php-fpm.conf #write something into readme.txt echo 