/usr/local/sbin/php-fpm -c $(php-config --prefix)/lib/php.ini -y /usr/local/etc/php-fpm.conf
stop php-fpm:
kill -INT 'cat /usr/local/php/var/run/php-fpm.pid'
OR
service php-fpm stop
reboot php-fpm:
kill -USR2 'cat /usr/local/php/var/run/php-fpm.pid'
OR
service php-fpm reboot" >> ../readme.txt #config nginx mv /etc/nginx/conf.d/default.conf /etc/nginx/conf.d/default.conf.bak echo -e "server
