 PHP_ADD_LIBRARY(clntsh, 1, PDO_OCI_SHARED_LIBADD)
 \;\;' config.m4 &amp;&amp; sed -i '10i elif test -f \$PDO_OCI_DIR/lib/libclntsh\.\$SHLIB_SUFFIX_NAME.11.2\; then
 PDO_OCI_VERSION=11\.2' config.m4 &amp;&amp; sed -i 's/function_entry/zend_function_entry/g' pdo_oci.c &amp;&amp; phpize &amp;&amp; ./configure --with-pdo-oci=instantclient,/usr,11.2 &amp;&amp; make &amp;&amp; make install &amp;&amp; echo "extension=pdo_oci.so" >> $(php-config --prefix)/lib/php.ini &amp;&amp; cd ../ } function download_phalcon() { git clone --depth=1 git://github.com/phalcon/cphalcon.git } function install_phalcon() { #install phalcon frameworks cd cphalcon/build &amp;&amp; ./install &amp;&amp; echo "extension=phalcon.so" >> $(php-config --prefix)/lib/php.ini &amp;&amp; cd ../../ } function download_jdk() { #  } function install_jdk() { install_path=$(pwd) &amp;&amp; mkdir -p /usr/java &amp;&amp; cp -rf jdk-8u111-linux-x64.tar.gz /usr/java/ &amp;&amp; cd /usr/java &amp;&amp; tar -zxvf jdk-8u111-linux-x64.tar.gz &amp;&amp; echo -e "JAVA_HOME=/usr/java/jdk1.8.0_111
CLASSPATH=\$JAVA_HOME/lib/
PATH=\$PATH:\$JAVA_HOME/bin:\$JAVA_HOME/jre/bin
export PATH JAVA_HOME CLASSPATH" >> /etc/profile &amp;&amp; source /etc/profile &amp;&amp; java -version &amp;&amp; cd $install_path } function install_openssl() { yum -y install openssl mod_ssl cd /etc/pki/tls/private/ &amp;&amp; openssl genrsa 1024 >localhost.key &amp;&amp; openssl req -new -key localhost.key > localhost.csr &amp;&amp; openssl req -x509 -days 3650 -key localhost.key -in localhost.csr > localhost.crt &amp;&amp; cp localhost.crt /etc/pki/tls/certs/localhost.crt } function test_http() { echo -e "Alias /webalias "/var/www/alias\&rdquo;

