 Allow from all
" >> /etc/httpd/conf/httpd.conf echo -e "
 ServerAdmin admin@zhenzhidaole.com
 DocumentRoot /var/www/html
 ServerName www.zhenzhidaole.com
 ErrorLog /var/www/logs/error_log
 CustomLog /var/www/logs/access_log common
" >> /etc/httpd/conf/httpd.conf mkdir -p /var/www/web &amp;&amp; mkdir -p /var/www/alias echo "" > /var/www/alias/s.php echo -e "127.0.0.1 www.zhenzhidaole.com" >> /etc/hosts service httpd restart } function test_phpinfo() { php -v php -i |grep mcrypt php -i |grep ssh php -i |grep oci php -i |grep phalcon curl  -k curl  |grep oci # } init() install_httpd() #install_nginx() #download_php() install_php() #install_phpfpm() #download_mysql() install_mysql() #download_ssh2() install_ssh2() #download_oci() install_oci() #download_phalcon() install_phalcon() #download_jdk() install_jdk() install_openssl() #test_http() #test_phpinfo() &nbsp; 附件下载install-php.sh 另外附repo文件repo 📚 返回目录

